"""Re-label existing cases under the reframe. Deterministic, no LLM, no re-run, no tuning: reads each case's latest existing report.json.
belief grounding: quote verified in an agent message (msg:*) -> stated; verified only in code/helper/fn -> enacted; quote from the error or
unverified -> belief not established. Evidence kind: every existing case's error was captured by running the case's own scenario
(src/bin/capture-error.ts), so the only contradicting evidence is that scenario-captured error ("error-only, scenario-captured").
The old sandbox verdict becomes optional corroboration. Output: docs/reframe-relabel.md"""
import json, os
SRC = {c: f"artifacts/m13-v19a/{c}/report.json" for c in os.listdir("artifacts/m13-v19a") if not c.endswith(".log")}
SRC.update({"heldout5-citation-leaf": "artifacts/heldout5/heldout5-citation-leaf/report.json", "heldout5-macro-leapday": "artifacts/m8-v13-macro2/heldout5-macro-leapday/report.json", "heldout6-outcome-keys": "artifacts/heldout6/heldout6-outcome-keys/report.json"})
rows = []; tally = {}
for c in sorted(SRC):
    r = json.load(open(SRC[c])); cl = r.get("claim") or {}; p = r.get("provenance") or {}
    src = str(cl.get("belief_quote_source") or ""); ok = cl.get("belief_quote_verified")
    edit = bool(p.get("written_at"))
    if not edit: g, v = "-", "no_agent_edit"
    elif ok and src.startswith("msg:"): g, v = "stated", "belief_contradicted_error_only"
    elif ok and src.split(":")[0] in ("code", "helper", "fn"): g, v = "enacted", "belief_contradicted_error_only"
    else: g, v = "not grounded", "belief_unverified"
    tally[v] = tally.get(v, 0) + 1
    rows.append(f"| {c} | {'yes' if edit else 'no'} | {g} (`{src or '-'}`) | {v} | error-only, scenario-captured | {r.get('verdict')} | `{SRC[c]}` |")
out = ["# Existing cases re-labelled under the reframe", "", "Generated by `scripts/relabel-reframe.py` from existing reports (no re-run, no LLM, no tuning).", "",
       "Every existing case's error was captured by running that case's own scenario, so none has independent evidence: the best possible label is `belief_contradicted_error_only (scenario-captured)`. The sandbox verdict is kept as optional corroboration only. Claim correctness against the frozen success criteria is in docs/heldout-results.md and is not re-judged here.", "",
       "| case | agent edit found | belief grounding | reframe label | evidence kind | sandbox corroboration (old verdict) | report |", "|---|---|---|---|---|---|---|", *rows, "",
       "Totals: " + ", ".join(f"{k} {n}" for k, n in sorted(tally.items())) + f" (of {len(rows)}). Independent evidence: 0/{len(rows)}.",
       "Reports: held-out 5/6 from their official or latest re-runs; all others from the latest dev run m13-v19a (these cases are burned)."]
open("docs/reframe-relabel.md", "w").write("\n".join(out) + "\n"); print("\n".join(out[-3:]))
